function modelRecord(id){return config?.model_catalog?.models?.find(model=>model.id===id);}
function modelChoices(saved){const choices=(config?.model_catalog?.models||[]).map(model=>({value:model.id,label:model.label||model.id,...(['opus','sonnet','haiku'].includes(model.id)?{labelKey:{opus:'modelOpusLatest',sonnet:'modelSonnetLatest',haiku:'modelHaikuLatest'}[model.id]}:{})}));if(saved&&!choices.some(choice=>choice.value===saved))choices.unshift({value:saved,saved:true});return choices;}
function effortLevels(id,owner=false){const model=modelRecord(id);return !model||model.effort_supported===false?[]:(owner?model.chief_efforts:model.efforts)||[];}
function validChoice(choice,owner=false){const model=modelRecord(choice.model);if(!model)return false;return model.effort_supported===false?choice.effort==='':effortLevels(choice.model,owner).includes(choice.effort);}
function chooseModel(choice,id,owner=false){choice.model=id;const levels=effortLevels(id,owner);if(!levels.includes(choice.effort))choice.effort=levels.includes('medium')?'medium':levels[0]||'';}
function validDraft(){return Array.isArray(config?.model_catalog?.models)&&config.model_catalog.models.length>0&&Object.entries(routingState).every(([role,value])=>validChoice(value,role==='owner'))&&rosterState.every(slot=>validChoice(slot));}
