function t(key){return words[language][key]||key;}
function interpolate(key, values){return t(key).replace(/\{(\w+)\}/g,(_,name)=>values[name]??'');}
function locale(){return language==='tr'?'tr-TR':'en-US';}
function number(value){return new Intl.NumberFormat(locale(),{maximumFractionDigits:2}).format(value);}
function date(value){if(!value)return t('unknown');const parsed=new Date(value);return Number.isNaN(parsed.getTime())?t('unknown'):new Intl.DateTimeFormat(locale(),{dateStyle:'medium',timeStyle:'short'}).format(parsed);}
function day(value){if(!value)return t('unknown');const parsed=new Date(value+'T12:00:00');return Number.isNaN(parsed.getTime())?t('unknown'):new Intl.DateTimeFormat(locale(),{dateStyle:'medium'}).format(parsed);}
function node(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el;}
function details(summary,body){const el=node('details');el.append(node('summary',summary),node('pre',body));return el;}
async function api(path,data){
  const headers={'X-Console-Token':token};if(data!==undefined)headers['Content-Type']='application/json';
  const response=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers,body:data===undefined?undefined:JSON.stringify(data)});
  const value=await response.json();if(!response.ok){const error=new Error(value.error||'Request failed');error.code=response.status;error.kind=value.kind;throw error;}return value;
}
function friendlyError(error){if(error.code===403)return'errorAuth';if(!error.code)return'errorNetwork';if(/conflict|changed|stale|symlink|manifest|restore/i.test(error.message))return'errorConflict';if(/OTLP|file|JSONL|usage|date|timestamp|MiB/i.test(error.message))return'errorFile';if(/invalid|unknown|must|range|integer|model|effort|parallel/i.test(error.message))return'errorInput';return'errorGeneral';}
function activity(key,error){activityKey=key;activityError=error;renderActivity();}
function renderActivity(){const box=$('activity');box.replaceChildren();box.classList.toggle('error',!!activityError);if(!activityKey)return;box.append(node('span',t(activityKey)));if(activityError)box.append(details(t('errorDetails'),activityError.message));}
const statusState=new Map();
function settingStatus(id,key,error){const changed=statusState.get(id)?.key!==key;statusState.set(id,{key,error});const box=$(id);box.replaceChildren();box.hidden=!key;box.classList.toggle('error',!!error);if(key)box.append(node('span',t(key)));if(error)box.append(details(t('errorDetails'),error.message));if(key&&changed){box.scrollIntoView({block:'nearest'});}}
async function action(fn){try{await fn();}catch(error){activity(friendlyError(error),error);}}
function clearUninstall(){uninstallData=undefined;$('uninstall-panel').hidden=true;$('uninstall-agree').checked=false;$('uninstall-do').disabled=true;}
function markDirty(){draftVersion++;$('preview').disabled=!validDraft();revision=undefined;previewData=undefined;$('preview-panel').hidden=true;clearUninstall();settingStatus('settings-status',null);settingStatus('save-status',null);renderSummary();renderTaskProfiles();}
function selectedPreset(){return $('preset').value;}
function currentName(){return !config?.installed?t('notSet'):t(presetNames[config.preset]||'custom');}
function pendingName(){return t(presetNames[selectedPreset()]||'custom');}
function differences(){
  if(!config)return [];
  const values=payload(),changes=[];
  if(config.preset!==values.preset)changes.push(interpolate('changedApproach',{before:currentName(),after:pendingName()}));
  if((config.roster||[]).length!==rosterState.length)changes.push(interpolate('helperChanged',{before:number(config.roster?.length||0),after:number(rosterState.length)}));
  else if(JSON.stringify(config.roster||[])!==JSON.stringify(rosterState))changes.push(t('changedTeamDuties'));
  const count=Object.entries(values.routing).filter(([role,choice])=>config.routing?.[role]?.model!==choice.model||config.routing?.[role]?.effort!==choice.effort).length;
  if(count)changes.push(interpolate('changedRoles',{count:number(count)}));
  const oldCount=config.max_parallelism==null?t('noHelperLimit'):number(Number(config.max_parallelism));
  if(String(config.max_parallelism??'')!==String(values.max_parallelism))changes.push(interpolate('changedHelpers',{before:oldCount,after:number(values.max_parallelism)}));
  return changes;
}
function renderSummary(){if(!config)return;renderPresetExplain();$('current-choice').textContent=currentName();$('current-note').textContent=config.installed?t('currentHelp'):t('needsInstall');$('pending-choice').textContent=pendingName();$('pending-note').textContent=config.installed?(differences().length?t('changedHelp'):t('noChanges')):t('pendingHelp');$('roster-current').textContent=config.roster?.length?interpolate('helperCurrent',{count:number(config.roster.length)}):t('helperNone');for(const radio of document.querySelectorAll('input[name=approach]'))radio.checked=radio.value===selectedPreset();}
function modelLabel(choice){return choice.saved?t('savedCustomModel')+' · '+choice.value:choice.labelKey?t(choice.labelKey):choice.label;}
function roles(routing){routingState=Object.fromEntries(Object.entries(routing).map(([role,value])=>[role,{...value}]));renderRoleDefaults();renderModelNote();}
function choiceGroup(titleKey,choices,current,onChoose,groupClass='choice-chips'){
  const group=node('div',undefined,groupClass);group.setAttribute('role','group');group.setAttribute('aria-label',t(titleKey));
  for(const choice of choices){const button=node('button',choice.label,'choice-chip');button.type='button';button.dataset.value=choice.value;button.setAttribute('aria-pressed',String(choice.value===current));button.addEventListener('click',()=>{const inspector=!!group.closest('#team-inspector');const card=group.closest('.role-default-card');const cardIndex=card?[...card.parentElement.children].indexOf(card):-1;onChoose(choice.value);markDirty();renderRoster();renderRoleDefaults();const scope=inspector?$('team-inspector'):cardIndex>=0?$('roles').children[cardIndex]:null;const replacement=[...(scope?.querySelectorAll('[role=group]')||[])].find(item=>item.getAttribute('aria-label')===t(titleKey));[...(replacement?.querySelectorAll('[data-value]')||[])].find(item=>item.dataset.value===choice.value)?.focus();});group.append(button);}
  return group;
}
function modelCards(value,onChoose){return choiceGroup('model',modelChoices(value).map(choice=>({value:choice.value,label:modelLabel(choice)})),value,onChoose,'model-cards');}
function effortChips(value,onChoose,owner=false,modelId){const levels=effortLevels(modelId,owner);const content=node('div');if(levels.length)content.append(node('p',t('effort'),'field-label'),choiceGroup('effort',levels.map(level=>({value:level,label:t(({low:'effortLow',medium:'effortMedium',high:'effortHigh',xhigh:'effortXhigh',max:'effortMax'})[level])})),value,onChoose));else content.append(node('p',t('modelHaikuNote'),'field-help'));if(!validChoice({model:modelId,effort:value},owner))content.append(node('p',t('modelCorrection'),'error'));return content;}
function renderRoleDefaults(){const area=$('roles');area.replaceChildren();if(!config)return;for(const [role,values] of Object.entries(routingState)){const card=node('div',undefined,'role-default-card');card.append(node('h4',t(roleNames[role]||'unknown')));card.append(node('p',t('model'),'field-label'),modelCards(values.model,value=>{chooseModel(routingState[role],value,role==='owner');$('preset').value='custom';renderModelNote();}));card.append(effortChips(values.effort,value=>{routingState[role].effort=value;$('preset').value='custom';},role==='owner',values.model));area.append(card);}}
function translateRoleLabels(){renderRoleDefaults();}
function renderPresetExplain(){const key={balanced:'presetExplainBalanced',quality:'presetExplainQuality',economy:'presetExplainEconomy','quota-saver':'presetExplainQuota',custom:'presetExplainCustom'}[selectedPreset()]||'presetExplainCustom';$('preset-explain').textContent=t(key);}
function renderModelNote(){if(!config?.model_catalog?.models?.length){$('model-specific-note').hidden=false;$('model-specific-note').textContent=t('modelCatalogMissing');return;}const selected=[...Object.values(routingState).map(value=>value.model),...rosterState.map(slot=>slot.model)].some(value=>modelRecord(value)?.effort_supported===false);$('model-specific-note').hidden=!selected;$('model-specific-note').textContent=selected?t('modelHaikuNote'):'';}

